#!/usr/bin/env node
// Copyright (c) Meta Platforms, Inc. and affiliates.

/**
 * @file Generate (or verify) the probe theme from Core's generated contract.
 *
 * @input  packages/core/theme-visual-props.json
 * @output packages/themes/probe/src/probeTheme.ts, and a coverage summary
 *
 * `--check` makes it a CI guard: adding a theming target without regenerating
 * fails the build, which is the whole point — a target that nobody remembered
 * to cover is exactly the target that silently stops working.
 *
 * Usage:
 *   node .github/scripts/visual-gate/generate-probe-theme.mjs [--check]
 */

import * as fs from 'node:fs';
import * as path from 'node:path';
import {fileURLToPath} from 'node:url';

import {buildProbeComponents, renderProbeTheme} from './lib/probe-theme.mjs';
import {PROBE_FONT, PROBE_SYNTAX, PROBE_TOKENS} from './lib/probe-axes.mjs';
import {loadThemeVisualPropsContract} from '../../../packages/cli/foundation/discovery/theme-visual-props.mjs';

const REPO_ROOT = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../../..',
);
const OUT = path.join(REPO_ROOT, 'packages/themes/probe/src/probeTheme.ts');
const CONFIG_OUT = path.join(
  REPO_ROOT,
  'packages/themes/probe/src/probeConfig.ts',
);

/**
 * The non-component axes, emitted as TypeScript.
 *
 * Generated rather than hand-kept so the values the theme SETS and the values
 * the gate ASSERTS are the same literals. Two copies of a fixture drift, and
 * the check would then report the drift as a broken theme.
 */
function renderProbeConfig() {
  const json = value => JSON.stringify(value, null, 2).replace(/"/g, "'");
  return `// Copyright (c) Meta Platforms, Inc. and affiliates.
// @generated by .github/scripts/visual-gate/generate-probe-theme.mjs — do not edit.
//
// The non-component axes of the probe theme, generated from
// .github/scripts/visual-gate/lib/probe-axes.mjs.

import type {SyntaxThemeTokenInput} from '@astryxdesign/core/theme';

/** Tokens the probe overrides, observable on any themed subtree. */
export const PROBE_TOKENS: Record<string, string> = ${json(PROBE_TOKENS)};

/** A font stack that can only have come from the theme. */
export const PROBE_FONT = '${PROBE_FONT.replace(/'/g, "\\'")}';

// Not annotated: the literal keys and tuple shapes ARE the contract
// (SyntaxThemeTokenInput requires all fourteen), so widening this to a Record
// would hide a missing token behind a type that accepts anything.
/** Syntax-token colours as [light, dark] pairs, one unmistakable value each. */
export const PROBE_SYNTAX: SyntaxThemeTokenInput = ${json(PROBE_SYNTAX)};
`;
}
const check = process.argv.includes('--check');

const coreRoot = path.join(REPO_ROOT, 'packages/core');
const contract = loadThemeVisualPropsContract(coreRoot);
if (!contract) {
  throw new Error(
    `Missing or unsupported ${path.relative(REPO_ROOT, path.join(coreRoot, 'theme-visual-props.json'))}. ` +
      'Run: pnpm generate:theme-visual-props',
  );
}
const built = buildProbeComponents(contract);

// Format with the repo's own prettier config. The pre-commit hook formats
// every staged .ts, so a generator emitting anything else would produce a file
// that is reformatted the moment it is committed — and `--check` would then
// fail on every run afterwards, for a difference in whitespace.
const prettier = await import('prettier');
const options = await prettier.resolveConfig(OUT);
const source = await prettier.format(renderProbeTheme(built), {
  ...options,
  filepath: OUT,
});
const configSource = await prettier.format(renderProbeConfig(), {
  ...options,
  filepath: CONFIG_OUT,
});

if (check) {
  const currentConfig = fs.existsSync(CONFIG_OUT)
    ? fs.readFileSync(CONFIG_OUT, 'utf8')
    : '';
  if (currentConfig !== configSource) {
    process.stderr.write(
      '::error::The probe theme config is out of date — a theme axis changed without regenerating it.\n' +
        'Run: pnpm visual:probe-theme\n',
    );
    process.exit(1);
  }
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (current !== source) {
    process.stderr.write(
      '::error::The probe theme is out of date — a theming target changed without regenerating it.\n' +
        'A target the probe theme does not cover is a target the visual gate cannot verify.\n' +
        'Run: pnpm visual:probe-theme\n',
    );
    process.exit(1);
  }
  process.stdout.write(
    `✅ probe theme current — ${built.coverage.targets} targets, ${built.coverage.selectors} selectors.\n`,
  );
  process.exit(0);
}

fs.mkdirSync(path.dirname(OUT), {recursive: true});
fs.writeFileSync(OUT, source);
fs.writeFileSync(CONFIG_OUT, configSource);
process.stdout.write(
  `Wrote ${path.relative(REPO_ROOT, OUT)} — ${built.coverage.targets} targets, ${built.coverage.selectors} selectors.\n`,
);
if (built.coverage.skipped.length > 0) {
  process.stdout.write(
    `\n${built.coverage.skipped.length} open or unresolved visual prop(s) have no finite selector set to probe:\n`,
  );
  for (const entry of built.coverage.skipped.slice(0, 15)) {
    process.stdout.write(`  ${entry.key}.${entry.prop} — ${entry.reason}\n`);
  }
  if (built.coverage.skipped.length > 15) {
    process.stdout.write(
      `  … and ${built.coverage.skipped.length - 15} more\n`,
    );
  }
}
